"use strict";(()=>{const data=window.LEARNWITHUS_COUNTRIES||[],region=document.getElementById('countryRegion'),search=document.getElementById('countrySearch'),grid=document.getElementById('countryGrid'),count=document.getElementById('countryCount');if(!grid)return;[...new Set(data.map(x=>x.region))].sort().forEach(r=>{const o=document.createElement('option');o.value=r;o.textContent=r;region.append(o)});grid.classList.add('country-explorer');const menu=document.createElement('div');menu.className='country-menu';menu.setAttribute('role','group');menu.setAttribute('aria-label','Choose a country');const detail=document.createElement('article');detail.className='country-selected';detail.setAttribute('aria-live','polite');grid.append(menu,detail);let chosen='';function render(){const q=search.value.trim().toLowerCase(),r=region.value,shown=data.filter(x=>(r==='all'||x.region===r)&&(!q||x.country.toLowerCase().includes(q)||x.capital.toLowerCase().includes(q)));menu.replaceChildren();shown.forEach(x=>{const b=document.createElement('button');b.type='button';b.textContent='';const flag=document.createElement('img');flag.className='country-picker-flag';flag.src='assets/country-flags/'+window.LWU_COUNTRY_FLAG_CODES?.[x.country]+'.png';flag.alt='Flag of '+x.country;b.append(flag,document.createTextNode(' '+x.country));b.className='country-choice'+(chosen===x.country?' selected':'');b.setAttribute('aria-pressed',String(chosen===x.country));b.onclick=()=>{chosen=x.country;draw(x);render()};menu.append(b)});count.textContent=shown.length+' countr'+(shown.length===1?'y':'ies')+' shown.';if(!shown.length)detail.innerHTML='<h3>No matching country</h3><p>Try a different search.</p>';else if(!shown.some(x=>x.country===chosen))draw(shown[0]);}function draw(x){chosen=x.country;detail.replaceChildren();const name=document.createElement('h3'),capital=document.createElement('p'),region=document.createElement('p');name.textContent='🌐 '+x.country;capital.textContent='Capital: '+x.capital;region.textContent='Region: '+x.region;const flag=document.createElement('img');flag.className='country-selected-flag';flag.src='assets/country-flags/'+window.LWU_COUNTRY_FLAG_CODES?.[x.country]+'.png';flag.alt='Flag of '+x.country;detail.append(flag,name,capital,region)}region.onchange=render;search.oninput=render;render();window.LearnWithUs?.recordComplete('countries-capitals.html')})();